#include <stdint.h>

// Define base memory addresses for RCC (Reset and Clock Control) and GPIOA
#define RCC_BASE      0x40023800
#define GPIOA_BASE    0x40020000

// Define register offsets
#define RCC_AHB1ENR   (*(volatile uint32_t *)(RCC_BASE + 0x30))
#define GPIOA_MODER   (*(volatile uint32_t *)(GPIOA_BASE + 0x00))
#define GPIOA_ODR     (*(volatile uint32_t *)(GPIOA_BASE + 0x14))

int main(void)
{
    // 1. Enable the clock for GPIOA (Bit 0 of AHB1ENR)
    RCC_AHB1ENR |= (1 << 0);

    // 2. Set PA5 as general purpose output (Bits 11:10 = 01 in MODER)
    // Clear bits 10 and 11 first, then set bit 10
    GPIOA_MODER &= ~(3 << 10);
    GPIOA_MODER |=  (1 << 10);

    /* Loop forever */
    for(;;)
    {
        // 3. Turn ON the LED by setting Output Data Register bit 5 high
        GPIOA_ODR |= (1 << 5);
        
        // Simple delay loop
        for(volatile int i = 0; i < 50000; i++);

        // 4. Turn OFF the LED by clearing Output Data Register bit 5
        GPIOA_ODR &= ~(1 << 5);
        
        // Simple delay loop
        for(volatile int i = 0; i < 10000; i++);
    }
}